CREATE OR REPLACE SCHEMASTORE VIEW obs_dhs_cameroon_2018_household_survey_coverage WITH CONTAINER cross_examiner AS
SELECT
    item.country AS country,
    CASE WHEN item.country = 'Cameroon' THEN 'CMR' ELSE '' END AS country_iso3,
    item.antigen AS antigen,
    item.year AS reporting_year,
    'Household survey coverage' AS measure,
    'survey' AS metric_type,
    'household_survey' AS measurement_kind,
    CAST(item.value_percent AS DOUBLE) AS value_percent,
    'percent' AS unit,
    'Children 12-23 months' AS denominator,
    'Measles (MCV1) coverage from a household survey' AS definition,
    'dhs_cameroon_2018' AS source_id,
    'pdf' AS source_type,
    'Cameroon DHS 2018 survey report' AS source_name,
    item.source_url AS source_ref,
    'cameroon_household_survey' AS origin_id,
    'Cameroon household survey coverage (independent household sampling)' AS origin_label,
    '' AS derived_from,
    false AS is_derived,
    false AS is_synthetic,
    true AS independent_capable,
    'INDEPENDENT_MEASUREMENT' AS verification_scope,
    'transcribed_from_publication' AS verification_status,
    item.notes AS notes
FROM cross_examiner_evidence.survey_figures_raw LATERAL VIEW explode(evidence) AS item
WHERE item.measure = 'Household survey coverage' AND item.country = 'Cameroon' AND item.source_url = 'https://dhsprogram.com/pubs/pdf/SR266/SR266.pdf';

