CREATE OR REPLACE SCHEMASTORE VIEW obs_worldbank_wdi_wuenic_estimate WITH CONTAINER cross_examiner AS
SELECT
    'Cameroon' AS country,
    item.countryiso3code AS country_iso3,
    'MCV1' AS antigen,
    item.date AS reporting_year,
    'WUENIC estimate' AS measure,
    'wuenic' AS metric_type,
    'reconciled_estimate' AS measurement_kind,
    CAST(item.value AS DOUBLE) AS value_percent,
    'percent' AS unit,
    'Children 12-23 months' AS denominator,
    'World Bank indicator SH.IMM.MEAS' AS definition,
    'worldbank_wdi' AS source_id,
    'rest_json' AS source_type,
    'World Bank Indicators (SH.IMM.MEAS)' AS source_name,
    'https://api.worldbank.org/v2/country/CMR/indicator/SH.IMM.MEAS' AS source_ref,
    'wuenic_2025' AS origin_id,
    'WHO/UNICEF Estimates of National Immunization Coverage (WUENIC), 2025 revision' AS origin_label,
    'wuenic_workbook_2025' AS derived_from,
    true AS is_derived,
    false AS is_synthetic,
    false AS independent_capable,
    'SELF_CONSISTENCY' AS verification_scope,
    'verified_against_source_table' AS verification_status,
    'Indicator SH.IMM.MEAS, measles vaccination coverage' AS notes
FROM world_bank_indicators.cmr_measles_coverage LATERAL VIEW explode(from_json(get_json_object(_corrupt_record, '$[1]'), 'array<struct<indicator:struct<id:string,value:string>,country:struct<id:string,value:string>,countryiso3code:string,date:string,value:string,unit:string,obs_status:string,decimal:int>>')) AS item;

